package app.blaxyt.mod;
import java.util.*;import java.lang.reflect.*;import android.text.Spannable;import android.widget.TextView;
public class InteractionChecks{
 static int tests;static void check(boolean b,String s){tests++;if(!b)throw new AssertionError(s);}
 static String body="Голосовое BlaxyT. 0:12 · Слушать: ТГК @BlaxyT [blaxy-voice:0123456789abcdef0123456789abcdef]";
 static class Spans implements InvocationHandler{
 String text;Map<Object,int[]> marks=new HashMap<>();Spans(String s){text=s;}
 Spannable value(){return (Spannable)Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{Spannable.class},this);}
 public Object invoke(Object p,Method m,Object[] a){switch(m.getName()){
 case "length":return text.length();case "toString":return text;case "charAt":return text.charAt((Integer)a[0]);case "subSequence":return text.subSequence((Integer)a[0],(Integer)a[1]);
 case "getSpans":{Class<?> c=(Class<?>)a[2];List<Object> found=new ArrayList<>();for(Object x:marks.keySet())if(c.isInstance(x))found.add(x);Object arr=Array.newInstance(c,found.size());for(int i=0;i<found.size();i++)Array.set(arr,i,found.get(i));return arr;}
 case "setSpan":marks.put(a[0],new int[]{(Integer)a[1],(Integer)a[2]});return null;case "removeSpan":marks.remove(a[0]);return null;
 default:throw new AssertionError(m.getName());}}
 }
 public static void main(String[] args)throws Exception{
 TextView row=new TextView();Map<String,Object> model=new HashMap<>(),cell=new HashMap<>();model.put("getUser",Map.of("getUid","123456789"));model.put("getText",body);model.put("getAwemeId","987654321");cell.put("D6",model);cell.put("q6",Map.of("getAid","987654321"));VoiceComments.bind(cell,row);
 Spans store=new Spans(body);Spannable text=store.value();VoiceComments.mark(row,text);check(store.marks.size()==2,"voice drawing and tap spans");
 for(int[] range:store.marks.values())check(range[0]==0&&range[1]==body.length(),"whole transport hidden");
 VoiceComments.mark(row,text);check(store.marks.size()==2,"rebinding does not accumulate spans");
 Spans unrelated=new Spans("Обычный комментарий");VoiceComments.mark(row,unrelated.value());check(unrelated.marks.isEmpty(),"different text unchanged");
 model.put("getText","Обычный комментарий");VoiceComments.bind(cell,row);VoiceComments.mark(row,text);check(store.marks.isEmpty(),"recycled row clears player");
 for(float v:new float[]{.5f,1f,2f,3f,4f,5f}){
 PlayerTools.value=v;String label=SpeedGesture.captionText("2x скорость");check(label.startsWith((v==(int)v?Integer.toString((int)v):Float.toString(v))+"x"),"hold caption "+v);
 Map<String,Object> owner=new HashMap<>();owner.put("LLLLLZ",true);SpeedGesture.begin(owner);check(SpeedGesture.engineRate(2f)==v,"engine during hold");owner.put("LLLLLZ",false);check(SpeedGesture.engineRate(2f)==2f,"release restores normal");}
 check(SpeedGesture.captionText("12x").equals("12x"),"do not replace larger numbers");
 List<Float> original=Collections.unmodifiableList(Arrays.asList(.5f,1f,1.5f,2f));List<Float> extended=PlaybackSpeeds.extend(original);check(extended.equals(Arrays.asList(.5f,1f,1.5f,2f,3f,4f,5f)),"native list includes all speeds");check(original.size()==4,"source is not mutated");check(PlaybackSpeeds.extend(extended).equals(extended),"no duplicates");
 Field mode=Performance.class.getDeclaredField("mode");mode.setAccessible(true);mode.setInt(null,1);android.view.View v=new android.view.View();Performance.redraw(v);check(v.delayed==33&&v.frames==0,"economy decorative frame budget");v.delayed=0;v.visible=false;Performance.redraw(v);check(v.delayed==0&&v.frames==0,"offscreen sleeps");v.visible=true;v.focused=false;Performance.redraw(v);check(v.delayed==0,"background sleeps");v.focused=true;mode.setInt(null,2);Performance.redraw(v);check(v.frames==1,"full effects restored");
 System.out.println(tests+" voice-card, speed-menu/hold and redraw lifecycle checks passed");
 }
}
